import { hostMatches } from './host';
import { normalize, words } from './text';

/*
 * Generic AI-widget detection for sites without a dedicated rule (T-009).
 *
 * Precision over recall: hiding real content is worse than missing a feature. Every detector needs a decisive signal or
 * several weak ones agreeing, and every hit passes `isSafeToHide`. Signal strengths:
 *
 *   decisive  exact AI action label on a control ("Ask AI")         → control
 *             known AI widget vendor container (Kapa, Inkeep, …)    → vendor
 *   strong    AI disclaimer text ("AI-generated", "Generated by AI")  (needs an AI-marked container → region)
 *   weak      ✨ / sparkle icon · AI word in class/id · AI verb label ("Summarize")  (control needs ≥ 2)
 *
 * Deliberately NOT signals on their own: the word "AI" in prose, headings, or navigation links, and generic
 * support-chat launchers (e.g. Intercom), which can't be told apart from human support without markup we
 * haven't verified.
 */

export type HeuristicKind = 'control' | 'region' | 'vendor';
export const HEURISTIC_PREFIX = 'heuristic.';

export interface HeuristicHit {
  readonly element: Element;
  readonly kind: HeuristicKind;
}

/** Sites whose product *is* AI. The user went there on purpose, so heuristics stay off (site rules still apply). */
const AI_PRODUCT_HOSTS = [
  'chatgpt.com',
  'chat.openai.com',
  'openai.com',
  'claude.ai',
  'anthropic.com',
  'gemini.google.com',
  'aistudio.google.com',
  'notebooklm.google.com',
  'copilot.microsoft.com',
  'perplexity.ai',
  'poe.com',
  'character.ai',
  'grok.com',
  'x.ai',
  'meta.ai',
  'mistral.ai',
  'deepseek.com',
  'huggingface.co',
];

export function isHeuristicsExcludedHost(host: string): boolean {
  return AI_PRODUCT_HOSTS.some((pattern) => hostMatches(host, pattern));
}

// ── signals ────────────────────────────────────────────────────────────────

const MAX_LABEL_LENGTH = 60;
const MAX_REGION_TEXT = 4000;

/** Decorative glyphs that often decorate AI buttons. Stripped before label matching. */
const DECORATION = /[✨✦✧⭐★\u{1F916}\u{1FA84}]/gu;
const SPARKLE_CHAR = /[✨✦✧\u{1FA84}]/u;

/** Exact (normalized) action labels: decisive on their own when on a control. */
const ACTION_LABELS: readonly RegExp[] = [
  /^(ask|chat with|talk to) (the |our )?ai( assistant)?$/,
  /^ai (assistant|chat|summary|summari[sz]e|answer|answers)$/,
  /^(summari[sz]e|explain|rewrite|improve|write|generate|draft|translate)( this| it| text| page| article| post| thread| reviews?)? (with|using) ai$/,
  /^help me write$/,
  // Finnish
  /^kysy tekoälyltä$/,
  /^tekoälyavustaja$/,
  /^tiivistä tekoälyllä$/,
];

/** First words of a label that hint at an AI action. Weak: never enough alone. */
const ACTION_VERBS = new Set([
  'summarize',
  'summarise',
  'summary',
  'ask',
  'explain',
  'rewrite',
  'improve',
  'generate',
  'draft',
  'tiivistä',
  'kysy',
]);

/**
 * Provenance disclaimers, matched against a short standalone element (small print), not prose. A disclaimer
 * must *start* the element ("AI-generated from customer reviews", "AI responses may include mistakes") or warn
 * about AI mistakes. Marketing copy like "…, powered by AI." deliberately doesn't count.
 */
const DISCLAIMER_START =
  /^(ai[- ]generated|((this|the) )?(summary|answer|answers|content|overview|response|responses|text|reply) (is |was |were |are )?(generated|created|written) (by|with|using) (ai|artificial intelligence)|generated (by|with|using) (ai|artificial intelligence)|ai (responses|answers|summaries|content|overviews?) (may|can|might) (contain|include|be|make)|tekoälyn (luoma|tuottama|tuottamat|antamat))\b/;
const MISTAKES_WARNING =
  /\b(ai|generative ai|artificial intelligence)\b.{0,60}\b(may|can|might) (contain|include|make|have) (mistakes|errors|inaccuracies)\b/;
const MAX_DISCLAIMER_LENGTH = 160;
const SMALL_PRINT = 'p, span, small, div, footer, figcaption, li, em, i, sup, aside';

/** Words that, next to "ai", mark an identifier as an AI feature (`ai-summary`, `askAi`, `btnAi`). */
const AI_PARTNERS = new Set([
  'ask',
  'summary',
  'summaries',
  'summarize',
  'summarise',
  'assistant',
  'assist',
  'answer',
  'answers',
  'overview',
  'generated',
  'powered',
  'chat',
  'widget',
  'insights',
  'highlights',
  'helper',
  'agent',
  'button',
  'btn',
  'sparkle',
  'suggestion',
  'suggestions',
  'writer',
  'compose',
  'reply',
]);
const AI_WORDS = new Set(['askai', 'aiassistant', 'genai', 'chatbot', 'copilot']);

/** Third-party AI widget vendors. Decisive: these containers only ever hold the AI widget. */
const VENDOR_WORDS = new Set(['inkeep', 'mendable', 'docsbot', 'chatbase', 'sitegpt']);
const KAPA_PARTNERS = new Set(['widget', 'ai', 'button', 'modal', 'container', 'root']);

const SPARKLE_ICON =
  '[class*="sparkle" i], [data-icon*="sparkle" i], [aria-label*="sparkle" i], img[alt*="sparkle" i], use[href*="sparkle" i]';

/** Elements that act as buttons. Links with a real href navigate somewhere, so they're excluded on purpose. */
export const CONTROL_SELECTOR =
  'button, [role="button"], summary, a:not([href]), a[href="#"], a[href^="javascript:" i], a[aria-haspopup], a[aria-controls], input[type="button"], input[type="submit"]';

/** Candidates for the AI-word signal. Prefiltered by substring, then confirmed by `words()`. */
const AI_MARKED_SELECTOR =
  '[class*="ai" i], [id*="ai" i], [class*="chatbot" i], [id*="chatbot" i], [class*="copilot" i], [aria-label*="ai" i]';

const VENDOR_SELECTOR = [
  ...[...VENDOR_WORDS, 'kapa'].flatMap((v) => [`[id*="${v}" i]`, `[class*="${v}" i]`]),
  '[class*="DocSearch-AskAi" i]',
].join(', ');

function identifiers(el: Element): string[] {
  const ids: string[] = [...el.classList];
  if (el.id) ids.push(el.id);
  const testId = el.getAttribute('data-testid');
  if (testId) ids.push(testId);
  return ids;
}

export function hasAiWord(el: Element): boolean {
  return identifiers(el).some((id) => {
    const w = words(id);
    return w.some(
      (word, i) =>
        AI_WORDS.has(word) ||
        (word === 'ai' && (AI_PARTNERS.has(w[i - 1] ?? '') || AI_PARTNERS.has(w[i + 1] ?? ''))),
    );
  });
}

export function isVendorWidget(el: Element): boolean {
  return identifiers(el).some((id) => {
    const w = words(id);
    if (w.some((word) => VENDOR_WORDS.has(word))) return true;
    if (w.some((word, i) => word === 'kapa' && KAPA_PARTNERS.has(w[i + 1] ?? ''))) return true;
    // Algolia DocSearch's "Ask AI" screen: DocSearch-AskAi…
    return w.includes('search') && w.some((word, i) => word === 'ask' && w[i + 1] === 'ai');
  });
}

/** Candidate labels for a control: aria-label, visible text, title, value. Normalized, decoration stripped. */
function labels(el: Element): string[] {
  const raw = [
    el.getAttribute('aria-label'),
    el.textContent,
    el.getAttribute('title'),
    el.getAttribute('value'),
  ];
  return raw
    .filter((t): t is string => t !== null && t.length <= MAX_LABEL_LENGTH * 2)
    .map((t) => normalize(t.replace(DECORATION, ' ')))
    .filter((t) => t !== '' && t.length <= MAX_LABEL_LENGTH);
}

function hasSparkle(el: Element): boolean {
  return (
    SPARKLE_CHAR.test(el.textContent) ||
    el.matches(SPARKLE_ICON) ||
    el.querySelector(SPARKLE_ICON) !== null
  );
}

// ── detectors ──────────────────────────────────────────────────────────────

/** A button-like element that opens or runs an AI feature. */
export function isAiControl(el: Element): boolean {
  const names = labels(el);
  if (names.some((name) => ACTION_LABELS.some((re) => re.test(name)))) return true;
  const verb = names.some((name) => {
    const first = name.split(' ')[0] ?? '';
    return ACTION_VERBS.has(first) && name.split(' ').length <= 3;
  });
  const score = (hasSparkle(el) ? 1 : 0) + (hasAiWord(el) ? 1 : 0) + (verb ? 1 : 0);
  return score >= 2;
}

function isDisclaimer(el: Element): boolean {
  const text = el.textContent;
  if (text.length > MAX_DISCLAIMER_LENGTH) return false;
  const normalized = normalize(text);
  return DISCLAIMER_START.test(normalized) || MISTAKES_WARNING.test(normalized);
}

/** A box that marks itself as AI (class/id/aria-label) and carries a standalone AI disclaimer. */
export function isAiRegion(el: Element): boolean {
  const aria = el.getAttribute('aria-label');
  const markedByLabel =
    aria !== null &&
    /^ai (summary|overview|assistant|answer|answers|insights|highlights)$/.test(normalize(aria));
  if (!markedByLabel && !hasAiWord(el)) return false;
  if (el.textContent.length > MAX_REGION_TEXT) return false;
  for (const small of el.querySelectorAll(SMALL_PRINT)) {
    if (isDisclaimer(small)) return true;
  }
  return false;
}

// ── safety ─────────────────────────────────────────────────────────────────

const NEVER_HIDE = 'html, head, body, main, article, [role="main"], [role="article"]';
const MUST_NOT_CONTAIN = 'main, article, [role="main"], [role="article"], h1';
const MAX_VIEWPORT_SHARE = 0.5;

/** Size guard: heuristics never hide page structure or anything covering most of the viewport. */
export function isSafeToHide(el: Element): boolean {
  if (el.matches(NEVER_HIDE) || el.querySelector(MUST_NOT_CONTAIN) !== null) return false;
  const view = el.ownerDocument.defaultView;
  if (view && view.innerWidth > 0 && view.innerHeight > 0) {
    const rect = el.getBoundingClientRect();
    if (rect.width * rect.height > MAX_VIEWPORT_SHARE * view.innerWidth * view.innerHeight)
      return false;
  }
  return true;
}

// ── scanning ───────────────────────────────────────────────────────────────

function* candidates(root: Element, selector: string): Generator<Element> {
  if (root.matches(selector)) yield root;
  yield* root.querySelectorAll(selector);
}

/**
 * Find AI widgets in `root` and its subtree. Hits are in document order, vendors and regions before
 * controls, so an outer widget wins over the controls inside it.
 */
export function findAiWidgets(root: Element): HeuristicHit[] {
  const hits: HeuristicHit[] = [];
  const collect = (selector: string, kind: HeuristicKind, test: (el: Element) => boolean) => {
    for (const el of candidates(root, selector)) {
      if (test(el) && isSafeToHide(el)) hits.push({ element: el, kind });
    }
  };
  collect(VENDOR_SELECTOR, 'vendor', isVendorWidget);
  collect(AI_MARKED_SELECTOR, 'region', isAiRegion);
  collect(CONTROL_SELECTOR, 'control', isAiControl);
  return hits;
}
